INSERT INTO forms (id, title, description, purpose, status, form_code, created_by_jid, created_at, opens_at, closes_at, archived_at, send_group_reminders, reminder_interval_days)
VALUES
  (1, 'Formulario de datos del estudiante y familia 2 grado', 'Su apoyo es muy importante. Con esta información podremos organizarnos mejor, facilitar la comunicación con las familias y estar preparados ante cualquier situación.', 'intake', 'open', 'FORM-1K2CL', '267469222600842@lid', '2026-03-11 18:36:29.80763', '2026-03-11 18:36:29.80411', NULL, NULL, FALSE, 0),
  (2, 'datos estudiantes 9no D', 'Buenas tardes, padres de familia. Los delegados y subdelegados de 9no grado hemos creado un formulario para recolectar datos específicos. Esto nos ayudará a organizar mejor las actividades del año y manejar de forma ordenada las actividades. Les pedimos su apoyo llenando el formulario. ¡Muchas gracias! \n\nLos va a dirigir al chat del asistente y allí deben contestar el formulario.', 'intake', 'closed', 'FORM-B0PJL', '82832789647522@lid', '2026-03-12 19:03:44.262066', '2026-03-12 19:08:23.715071', NULL, NULL, TRUE, 2),
  (3, 'Tallas para Sweters de Futbol', 'Formulario con el nombre de los 36 estudiantes y sus tallas', 'survey', 'open', 'FORM-O2DOJ', '267469222600842@lid', '2026-04-08 16:51:13.887161', '2026-04-08 16:51:13.875813', NULL, NULL, FALSE, 0),
  (4, 'Tallas de Suéteres Futbol', 'Indicar la talla de su acudido/a (tomar en cuenta que son dryfit y corren una talla menos que la regular)', 'intake', 'open', 'FORM-WDBWM', '196756830711849@lid', '2026-04-09 03:10:10.804424', '2026-04-09 03:10:10.79638', NULL, NULL, FALSE, 0),
  (5, 'Registro de tallas para el jersey de la mini liga', NULL, 'survey', 'open', 'FORM-09CGJ', '267469222600842@lid', '2026-04-09 13:48:31.645943', '2026-04-09 13:48:31.642357', NULL, NULL, FALSE, 0);
INSERT INTO form_questions (id, form_id, order, text, hint, type, answer_scope, required, options, profile_field)
VALUES
  (1, 1, 1, '¿Cuál es el nombre completo de su hijo/a?', '(Por favor, para identificar correctamente a cada estudiante).', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (2, 1, 2, '¿En qué salón o sección está su hijo/a?', '(Para ubicarlo/a correctamente dentro del grupo).', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (3, 1, 3, '¿Cuál es su nombre completo y parentesco con el niño/a?', '(Para saber con quién estamos en contacto: mamá, papá, acudiente, tutor, etc.).', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (4, 1, 4, '¿Cuál es su número principal de contacto?', '(Para comunicaciones importantes y avisos rápidos).', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (5, 1, 5, '¿Desea compartir un segundo número de contacto? Indique también de quién es.', '(Por si no logramos localizarle en el número principal).', 'text', 'parent', FALSE, $J$null$J$, NULL),
  (6, 1, 6, '¿Cuál es su correo electrónico principal?', '(Para enviar información más extensa, circulares o archivos cuando sea necesario).', 'text', 'parent', FALSE, $J$null$J$, NULL),
  (7, 1, 7, '¿Cuál es la fecha de cumpleaños de su hijo/a?', '(Para tener presente fechas especiales del grupo; solo día y mes si lo prefieren).', 'text', 'parent', FALSE, $J$null$J$, NULL),
  (9, 1, 8, '¿Su hijo/a tiene alguna alergia o intolerancia?', '(Para prevenir riesgos en celebraciones, meriendas, salidas o actividades, describa).', 'text', 'parent', FALSE, $J$null$J$, NULL),
  (19, 1, 9, '¿Hay algún otro dato importante que considere útil compartir?', '(Cualquier información que nos ayude a acompañar y coordinar mejor a su hijo/a durante el año).', 'text', 'parent', FALSE, $J$null$J$, NULL),
  (20, 1, 10, '¿Le gustaría apoyar como voluntario/a en alguna actividad del salón o del grupo?', '(Para saber con qué apoyo podemos contar en eventos, celebraciones o salidas).', 'yes_no', 'parent', TRUE, $J$null$J$, NULL),
  (22, 2, 1, 'Nombre del estudiante', NULL, 'text', 'parent', TRUE, $J$null$J$, NULL),
  (23, 2, 2, 'Nombre del acudiente', NULL, 'text', 'parent', TRUE, $J$null$J$, NULL),
  (24, 2, 3, 'Correo del acudiente', NULL, 'text', 'parent', TRUE, $J$null$J$, NULL),
  (25, 2, 4, 'Teléfono acudiente', NULL, 'text', 'parent', TRUE, $J$null$J$, NULL),
  (26, 2, 5, 'Desea participar como voluntario en las actividades de la promoción', NULL, 'yes_no', 'parent', TRUE, $J$null$J$, NULL),
  (27, 3, 1, '¿Cuál es la talla del suéter de su hijo/a?', 'Talla en número', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (29, 4, 1, 'Indicar talla de su hijo/a', 'Tallas de niños (2-4-6-8-10-12-14-16-18)', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (30, 5, 1, 'Cual es el tamaño de jersey de su acudido', 'por favor escriba *solo el numero.*   e.j.: 12, 14.. etc, _No valla a poner "Talla 12"_', 'text', 'parent', TRUE, $J$null$J$, NULL),
  (32, 5, 2, 'Algun nombre en especifico para para la parte de atras?', 'De no escribir nada usaremos el nombre de la lista.', 'text', 'parent', FALSE, $J$null$J$, NULL);
