INSERT INTO assignments (id, student_id, title, type, date, created_at, subject_id, description, materials, summary, updated_at, short_url)
VALUES
  (134103, 2036, 'Topic: Who are you?', 'Formativa', '2026-03-13', '2026-03-04 13:03:11', 4, '<p>Topic: Who are you?<\\/p>\r\n\r\n<p>Introduce themselves by sharing basic personal information (name, age, family, likes, and interests) using complete sentences and clear speaking voices.<\\/p>', '', 'Actividad para que los estudiantes se presenten compartiendo información personal usando oraciones completas y una voz clara.', '2026-03-05T03:18:19.379138', 'https://is.gd/z1HvmK'),
  (134100, 2036, 'Nouns', 'Formativa', '2026-03-12', '2026-03-04 13:00:53', 7, '<p>Topic: Nouns<\\/p>\r\n\r\n<p>Define a noun as a word that names a person, place, or thing.<\\/p>\r\n\r\n<p>Identify nouns in a sentence.<\\/p>\r\n\r\n<p>Classify nouns into categories:<\\/p>\r\n\r\n<ul>\r\n\t<li>Person<\\/li>\r\n\t<li>Place<\\/li>\r\n\t<li>Thing<\\/li>\r\n<\\/ul>\r\n\r\n<p> Use nouns correctly in sentences.<\\/p>\r\n\r\n<p> Explain why a word is a noun by telling whether it is a person, place, or thing.<\\/p>\r\n\r\n<p> <\\/p>', '', 'No materiales específicos necesarios para esta actividad, ya que se centra en el aprendizaje teórico sobre los sustantivos.', '2026-03-05T03:18:21.641332', 'https://is.gd/T6dVbb'),
  (134097, 2036, 'Story: Fun at School', 'Formativa', '2026-03-11', '2026-03-04 12:59:11', 3, '<p><strong>Story: "Fun at School"<\\/strong><\\/p>\r\n\r\n<p>Identify and answer the questions <em>who, what, when, and where<\\/em> in the story <strong>“Fun at School”<\\/strong> by listening, reading and finding details in the text.<\\/p>\r\n\r\n<p>Use book and reading notebook.<\\/p>', 'libro, cuaderno de lectura', 'Actividad de lectura y comprensión basada en la historia ''Fun at School'', donde los estudiantes identifican detalles y responden preguntas.', '2026-03-05T03:18:24.472818', 'https://is.gd/dIBgiM'),
  (134093, 2036, 'Story: Fun at School', 'Formativa', '2026-03-10', '2026-03-04 12:57:31', 3, '<p><strong>Story: "Fun at School"<\\/strong><\\/p>\r\n\r\n<p>Identify and answer the questions <em>who, what, when, and where<\\/em> in the story <strong>“Fun at School”<\\/strong> by listening, reading and finding details in the text.<\\/p>\r\n\r\n<p>Use book and reading notebook.<\\/p>', 'book, reading notebook', 'Los niños deben traer un libro y su cuaderno de lectura para identificar y responder preguntas sobre la historia ''Fun at School''.', '2026-03-05T03:18:26.777039', 'https://is.gd/AIj8ra'),
  (134090, 2036, 'Vocabulary #1: Fun at School', 'Formativa', '2026-03-09', '2026-03-04 12:55:49', 8, '<p>Topic: Vocabulary #1 (Textbook: Page 7)<\\/p>\r\n\r\n<p>Understand and use the vocabulary words:  <strong><em>count, pretend, draw, recess, field trip, classmates<\\/em><\\/strong> by identifying their meanings, using them in sentences, and illustrating them in class activities.<\\/p>\r\n\r\n<p>Use book and writing notebook.<\\/p>', 'libro de texto, cuaderno de escritura', 'Actividad para entender y usar vocabulario relacionado con la escuela, incluyendo identificar, usar en oraciones y dibujar las palabras.', '2026-03-05T03:18:28.719852', 'https://is.gd/Ki6ldC'),
  (134293, 2036, 'CONVIVENCIA ESCOLAR, DIOS QUIERE MI FELICIDAD, LA CUARESMA', 'Formativa', '2026-03-11', '2026-03-04 23:31:25', 21, '<p>Clase 2:Trabajo en el libro de texto y cuaderno. Reflexiona sobre la cuaresma. Comenta sobre el lema del ADN Lasallista “Todo está conectado”.<\\/p>', 'libro de texto, cuaderno', 'Actividad de reflexión sobre la cuaresma y el lema del ADN Lasallista, trabajando en el libro de texto y el cuaderno.', '2026-03-05T14:36:41.844266', 'https://is.gd/Vs2yjv'),
  (134290, 2036, 'ADAPTACIÓN ESCOLAR, DIOS QUIERE MI FELICIDAD, LA CUARESMA', 'Formativa', '2026-03-10', '2026-03-04 23:25:15', 21, '<p>Clase 1:Trabajo en el libro de texto y cuaderno. Reflexiona sobre la cuaresma. Comenta sobre el lema del ADN Lasallista.<\\/p>', 'libro de texto, cuaderno', 'Reflexión sobre la cuaresma y el lema del ADN Lasallista en la clase.', '2026-03-05T14:36:48.376811', 'https://is.gd/o9JaBW'),
  (134104, 2135, 'Topic: Who are you?', 'Formativa', '2026-03-13', '2026-03-04 13:03:13', 4, '<p>Topic: Who are you?<\\/p>\r\n\r\n<p>Introduce themselves by sharing basic personal information (name, age, family, likes, and interests) using complete sentences and clear speaking voices.<\\/p>', '', 'Actividad para que los estudiantes se presenten compartiendo información personal usando oraciones completas y una voz clara.', '2026-03-05T14:37:03.027257', 'https://is.gd/zrLlJJ'),
  (134295, 2135, 'CONVIVENCIA ESCOLAR, DIOS QUIERE MI FELICIDAD, LA CUARESMA', 'Formativa', '2026-03-13', '2026-03-04 23:34:08', 21, '<p>Clase 2: Trabajo en el libro de texto y cuaderno. Reflexiona sobre la cuaresma. Comenta sobre el lema del ADN Lasallista “Todo está conectado”.<\\/p>', 'libro de texto, cuaderno', 'Actividad de reflexión sobre la cuaresma y el lema del ADN Lasallista, trabajando en el libro de texto y el cuaderno.', '2026-03-05T14:37:05.559690', 'https://is.gd/y4LNtq'),
